-- Expand only current, eligible incomplete cohort/routes. A prefix job is a
-- scheduling hint; its publication never establishes contact or write evidence.
ALTER TABLE inventory_matching_coverage_jobs ADD COLUMN last_turn INTEGER NOT NULL DEFAULT 0 CHECK(last_turn>=0);
CREATE INDEX inventory_matching_coverage_job_turn ON inventory_matching_coverage_jobs(tenant,last_turn DESC);
CREATE INDEX inventory_matching_coverage_job_fair ON inventory_matching_coverage_jobs(tenant,generation_id,scope_id,config_version,last_turn,facet,node_hash) WHERE completed_version<work_version;
CREATE TABLE inventory_matching_coverage_pages (
 tenant TEXT NOT NULL, page_id TEXT NOT NULL, generation_id TEXT NOT NULL, scope_id TEXT NOT NULL, facet TEXT NOT NULL, node_hash TEXT NOT NULL,
 config_version INTEGER NOT NULL, domain_version INTEGER NOT NULL, source_set_version INTEGER NOT NULL, signal_clock INTEGER NOT NULL,
 work_version INTEGER NOT NULL, completed_version INTEGER NOT NULL, previous_turn INTEGER NOT NULL, next_turn INTEGER NOT NULL CHECK(next_turn>previous_turn),
 previous_destination TEXT NOT NULL, previous_source TEXT NOT NULL, previous_clock INTEGER NOT NULL CHECK(previous_clock>=0), previous_set TEXT NOT NULL,
 next_destination TEXT NOT NULL, next_source TEXT NOT NULL, next_clock INTEGER NOT NULL CHECK(next_clock>=0), next_set TEXT NOT NULL,
 limit_count INTEGER NOT NULL CHECK(limit_count BETWEEN 1 AND 10), set_count INTEGER NOT NULL CHECK(set_count BETWEEN 0 AND 10), row_count INTEGER NOT NULL CHECK(row_count BETWEEN 0 AND 200), complete INTEGER NOT NULL CHECK(complete IN(0,1)),
 lease_token TEXT NOT NULL, lease_fence INTEGER NOT NULL, input_digest TEXT NOT NULL, prepared_at INTEGER NOT NULL,
 state TEXT NOT NULL DEFAULT 'prepared' CHECK(state IN('prepared','committed')), PRIMARY KEY(tenant,page_id),
 FOREIGN KEY(tenant,generation_id,scope_id,facet,node_hash) REFERENCES inventory_matching_coverage_jobs(tenant,generation_id,scope_id,facet,node_hash),
 CHECK(set_count<=limit_count AND (complete=1 OR set_count=limit_count)),
 CHECK((set_count=0 AND row_count=0 AND complete=1 AND (next_destination,next_source,next_clock,next_set)=(previous_destination,previous_source,previous_clock,previous_set)) OR (set_count>0 AND (next_destination,next_source,next_clock,next_set)>(previous_destination,previous_source,previous_clock,previous_set)))
);
CREATE INDEX inventory_matching_coverage_page_prepared ON inventory_matching_coverage_pages(tenant,generation_id,scope_id,facet,node_hash,work_version) WHERE state='prepared';
CREATE TABLE inventory_matching_coverage_rows (
 tenant TEXT NOT NULL, page_id TEXT NOT NULL, destination TEXT NOT NULL, source_scope TEXT NOT NULL, record_key TEXT NOT NULL,
 source_config_version INTEGER NOT NULL, destination_config_version INTEGER NOT NULL, expected_work_version INTEGER NOT NULL, expected_completed_version INTEGER NOT NULL,
 PRIMARY KEY(tenant,page_id,destination,source_scope,record_key), FOREIGN KEY(tenant,page_id) REFERENCES inventory_matching_coverage_pages(tenant,page_id),
 FOREIGN KEY(tenant,destination) REFERENCES inventory_scopes(tenant,scope_id), FOREIGN KEY(tenant,source_scope) REFERENCES inventory_scopes(tenant,scope_id)
);
CREATE TABLE inventory_matching_coverage_guards (
 tenant TEXT NOT NULL, page_id TEXT NOT NULL, PRIMARY KEY(tenant,page_id), FOREIGN KEY(tenant,page_id) REFERENCES inventory_matching_coverage_pages(tenant,page_id)
);
CREATE VIEW inventory_matching_coverage_page_dependents AS
 SELECT p.tenant,p.page_id,p.generation_id,d.destination,d.source_scope,d.set_id,d.seen_clock,r.source_config_version,r.destination_config_version
 FROM inventory_matching_coverage_pages p CROSS JOIN inventory_matching_coverage_live_routes r CROSS JOIN inventory_matching_coverage_dependents d INDEXED BY inventory_matching_coverage_dependents_cursor
 WHERE r.tenant=p.tenant AND r.generation_id=p.generation_id AND d.tenant=r.tenant AND d.generation_id=r.generation_id AND d.scope_id=p.scope_id AND d.facet=p.facet AND d.node_hash=p.node_hash AND d.destination=r.destination AND d.source_scope=r.source_scope AND d.seen_clock<p.signal_clock
 AND (r.destination,r.source_scope)>=(p.previous_destination,p.previous_source) AND (r.destination,r.source_scope)<=(p.next_destination,p.next_source)
 AND (d.seen_clock,d.set_id)>(CASE WHEN (r.destination,r.source_scope)=(p.previous_destination,p.previous_source) THEN p.previous_clock ELSE -1 END,CASE WHEN (r.destination,r.source_scope)=(p.previous_destination,p.previous_source) THEN p.previous_set ELSE '' END)
 AND (d.seen_clock,d.set_id)<=(CASE WHEN (r.destination,r.source_scope)=(p.next_destination,p.next_source) THEN p.next_clock ELSE p.signal_clock END,CASE WHEN (r.destination,r.source_scope)=(p.next_destination,p.next_source) THEN p.next_set ELSE '' END);
CREATE VIEW inventory_matching_coverage_page_candidates AS
 SELECT d.tenant,d.page_id,d.generation_id,r.destination,r.source_scope,r.record_key,d.source_config_version,d.destination_config_version
 FROM inventory_matching_coverage_page_dependents d CROSS JOIN match_results r INDEXED BY match_result_set
 WHERE r.tenant=d.tenant AND r.set_id=d.set_id AND r.destination=d.destination AND r.source_scope=d.source_scope AND r.state='incomplete';
CREATE VIEW inventory_matching_coverage_page_remaining AS
 SELECT p.tenant,p.page_id FROM inventory_matching_coverage_pages p WHERE EXISTS(
 SELECT 1 FROM inventory_matching_coverage_live_routes r WHERE r.tenant=p.tenant AND r.generation_id=p.generation_id AND (r.destination,r.source_scope)>=(p.next_destination,p.next_source) AND EXISTS(
 SELECT 1 FROM inventory_matching_coverage_dependents d INDEXED BY inventory_matching_coverage_dependents_cursor WHERE d.tenant=r.tenant AND d.generation_id=r.generation_id AND d.scope_id=p.scope_id AND d.facet=p.facet AND d.node_hash=p.node_hash AND d.destination=r.destination AND d.source_scope=r.source_scope AND d.seen_clock<p.signal_clock AND (d.seen_clock,d.set_id)>(CASE WHEN (r.destination,r.source_scope)=(p.next_destination,p.next_source) THEN p.next_clock ELSE -1 END,CASE WHEN (r.destination,r.source_scope)=(p.next_destination,p.next_source) THEN p.next_set ELSE '' END)));
CREATE VIEW inventory_matching_coverage_page_stale AS
 SELECT p.tenant,p.page_id FROM inventory_matching_coverage_pages p WHERE NOT EXISTS(
 SELECT 1 FROM inventory_matching_coverage_jobs j JOIN comparison_domains d ON d.tenant=j.tenant AND d.active_generation=j.generation_id AND d.version=p.domain_version AND d.source_set_version=p.source_set_version
 JOIN inventory_comparison_ready_builds s ON s.tenant=j.tenant AND s.generation_id=j.generation_id AND s.scope_id=j.scope_id AND s.config_version=j.config_version
 JOIN inventory_matching_coverage_clocks clk ON clk.tenant=j.tenant AND clk.scope_id=j.scope_id AND clk.facet=j.facet AND clk.version>=j.signal_clock
 JOIN inventory_matching_coverage_dispatches h ON h.tenant=j.tenant AND h.dispatch_id=j.last_dispatch AND h.state='committed' AND h.generation_id=j.generation_id AND h.scope_id=j.scope_id AND h.facet=j.facet AND h.config_version=j.config_version AND h.scope_clock=j.signal_clock
 JOIN leases l ON l.tenant=j.tenant AND l.scope=json_array('matching-coverage-node',j.generation_id,j.scope_id,j.facet,j.node_hash) AND l.token=p.lease_token AND l.fence=p.lease_fence AND l.expires_at>unixepoch('subsec')*1000
 WHERE j.tenant=p.tenant AND j.generation_id=p.generation_id AND j.scope_id=p.scope_id AND j.facet=p.facet AND j.node_hash=p.node_hash AND j.config_version=p.config_version AND j.work_version=p.work_version AND j.signal_clock=p.signal_clock AND p.prepared_at>0 AND p.prepared_at<=unixepoch('subsec')*1000);
CREATE VIEW inventory_matching_coverage_invalid_rows AS
 SELECT q.tenant,q.page_id FROM inventory_matching_coverage_rows q JOIN inventory_matching_coverage_pages h ON h.tenant=q.tenant AND h.page_id=q.page_id WHERE NOT EXISTS(
 SELECT 1 FROM match_results r CROSS JOIN inventory_matching_coverage_dependents d
 WHERE r.tenant=q.tenant AND r.destination=q.destination AND r.source_scope=q.source_scope AND r.record_key=q.record_key AND r.state='incomplete'
 AND d.tenant=r.tenant AND d.set_id=r.set_id AND d.source_scope=r.source_scope AND d.scope_id=h.scope_id AND d.facet=h.facet AND d.node_hash=h.node_hash AND d.generation_id=h.generation_id AND d.destination=r.destination AND d.seen_clock<h.signal_clock
 AND (d.destination,d.source_scope,d.seen_clock,d.set_id)>(h.previous_destination,h.previous_source,h.previous_clock,h.previous_set) AND (d.destination,d.source_scope,d.seen_clock,d.set_id)<=(h.next_destination,h.next_source,h.next_clock,h.next_set));
CREATE VIEW inventory_matching_coverage_invalid_configurations AS
 SELECT h.tenant,h.page_id FROM inventory_matching_coverage_pages h WHERE EXISTS(
 SELECT 1 FROM (SELECT destination,source_scope,source_config_version,destination_config_version FROM inventory_matching_coverage_rows q WHERE q.tenant=h.tenant AND q.page_id=h.page_id GROUP BY destination,source_scope,source_config_version,destination_config_version) r
 WHERE NOT EXISTS(SELECT 1 FROM inventory_matching_coverage_live_routes rt WHERE rt.tenant=h.tenant AND rt.generation_id=h.generation_id AND rt.destination=r.destination AND rt.source_scope=r.source_scope AND rt.source_config_version=r.source_config_version AND rt.destination_config_version=r.destination_config_version));
CREATE TRIGGER inventory_matching_coverage_page_admit AFTER INSERT ON inventory_matching_coverage_pages BEGIN
 SELECT CASE WHEN NEW.state!='prepared' OR EXISTS(SELECT 1 FROM inventory_matching_coverage_page_stale WHERE tenant=NEW.tenant AND page_id=NEW.page_id) THEN RAISE(ABORT,'inventory matching coverage page authority changed') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_coverage_jobs j WHERE j.tenant=NEW.tenant AND j.generation_id=NEW.generation_id AND j.scope_id=NEW.scope_id AND j.facet=NEW.facet AND j.node_hash=NEW.node_hash AND j.work_version=NEW.work_version AND j.completed_version=NEW.completed_version AND j.completed_version<j.work_version AND j.last_turn=NEW.previous_turn AND (j.cursor_destination,j.cursor_source,j.cursor_clock,j.cursor_set)=(NEW.previous_destination,NEW.previous_source,NEW.previous_clock,NEW.previous_set)) OR NEW.next_turn!=(SELECT coalesce(max(last_turn),0)+1 FROM inventory_matching_coverage_jobs INDEXED BY inventory_matching_coverage_job_turn WHERE tenant=NEW.tenant) THEN RAISE(ABORT,'inventory matching coverage page frontier changed') END;
 SELECT CASE WHEN NEW.set_count!=(SELECT count(*) FROM inventory_matching_coverage_page_dependents WHERE tenant=NEW.tenant AND page_id=NEW.page_id) OR NEW.row_count!=(SELECT count(*) FROM inventory_matching_coverage_page_candidates WHERE tenant=NEW.tenant AND page_id=NEW.page_id) THEN RAISE(ABORT,'inventory matching coverage page census changed') END;
 SELECT CASE WHEN NEW.complete=1 AND EXISTS(SELECT 1 FROM inventory_matching_coverage_page_remaining WHERE tenant=NEW.tenant AND page_id=NEW.page_id) THEN RAISE(ABORT,'inventory matching coverage page range incomplete') END;
END;
CREATE TRIGGER inventory_matching_coverage_guard BEFORE INSERT ON inventory_matching_coverage_guards BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_coverage_pages h WHERE h.tenant=NEW.tenant AND h.page_id=NEW.page_id AND h.state='prepared' AND h.row_count=(SELECT count(*) FROM inventory_matching_coverage_rows WHERE tenant=h.tenant AND page_id=h.page_id)) OR EXISTS(SELECT 1 FROM inventory_matching_coverage_page_stale WHERE tenant=NEW.tenant AND page_id=NEW.page_id) THEN RAISE(ABORT,'inventory matching coverage manifest incomplete') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM inventory_matching_coverage_invalid_rows WHERE tenant=NEW.tenant AND page_id=NEW.page_id) THEN RAISE(ABORT,'inventory matching coverage row changed') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM inventory_matching_coverage_invalid_configurations WHERE tenant=NEW.tenant AND page_id=NEW.page_id) THEN RAISE(ABORT,'inventory matching coverage configuration changed') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM inventory_matching_coverage_rows q JOIN inventory_matching_coverage_pages h ON h.tenant=q.tenant AND h.page_id=q.page_id LEFT JOIN matching_work w ON w.tenant=q.tenant AND w.generation_id=h.generation_id AND w.destination=q.destination AND w.source_scope=q.source_scope AND w.record_key=q.record_key WHERE q.tenant=NEW.tenant AND q.page_id=NEW.page_id AND (q.expected_work_version!=coalesce(w.work_version,0) OR q.expected_completed_version!=coalesce(w.completed_version,0))) THEN RAISE(ABORT,'inventory matching coverage work changed') END;
END;
DROP TRIGGER inventory_matching_coverage_job_progress;
CREATE TRIGGER inventory_matching_coverage_job_progress BEFORE UPDATE ON inventory_matching_coverage_jobs WHEN NEW.work_version=OLD.work_version AND (NEW.completed_version,NEW.cursor_destination,NEW.cursor_source,NEW.cursor_clock,NEW.cursor_set,NEW.last_turn) IS NOT (OLD.completed_version,OLD.cursor_destination,OLD.cursor_source,OLD.cursor_clock,OLD.cursor_set,OLD.last_turn) BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_coverage_pages p INDEXED BY inventory_matching_coverage_page_prepared JOIN inventory_matching_coverage_guards g ON g.tenant=p.tenant AND g.page_id=p.page_id WHERE p.tenant=OLD.tenant AND p.generation_id=OLD.generation_id AND p.scope_id=OLD.scope_id AND p.facet=OLD.facet AND p.node_hash=OLD.node_hash AND p.work_version=OLD.work_version AND p.completed_version=OLD.completed_version AND p.previous_turn=OLD.last_turn AND p.next_turn=NEW.last_turn AND (p.previous_destination,p.previous_source,p.previous_clock,p.previous_set)=(OLD.cursor_destination,OLD.cursor_source,OLD.cursor_clock,OLD.cursor_set) AND (p.next_destination,p.next_source,p.next_clock,p.next_set)=(NEW.cursor_destination,NEW.cursor_source,NEW.cursor_clock,NEW.cursor_set) AND NEW.completed_version=CASE p.complete WHEN 1 THEN p.work_version ELSE p.completed_version END AND p.state='prepared' AND NOT EXISTS(SELECT 1 FROM inventory_matching_coverage_page_stale x WHERE x.tenant=p.tenant AND x.page_id=p.page_id)) THEN RAISE(ABORT,'inventory matching coverage progress guard missing') END;
END;
CREATE TRIGGER inventory_matching_coverage_job_turn_guard BEFORE UPDATE ON inventory_matching_coverage_jobs WHEN NEW.last_turn<OLD.last_turn OR (NEW.work_version!=OLD.work_version AND NEW.last_turn!=OLD.last_turn) BEGIN SELECT RAISE(ABORT,'inventory matching coverage turn regressed'); END;
CREATE TRIGGER inventory_matching_coverage_page_commit BEFORE UPDATE ON inventory_matching_coverage_pages BEGIN
 SELECT CASE WHEN OLD.state!='prepared' OR NEW.state!='committed' OR NOT EXISTS(SELECT 1 FROM inventory_matching_coverage_guards WHERE tenant=OLD.tenant AND page_id=OLD.page_id) OR EXISTS(SELECT 1 FROM inventory_matching_coverage_page_stale WHERE tenant=OLD.tenant AND page_id=OLD.page_id) THEN RAISE(ABORT,'inventory matching coverage page commit changed') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_coverage_jobs j WHERE j.tenant=OLD.tenant AND j.generation_id=OLD.generation_id AND j.scope_id=OLD.scope_id AND j.facet=OLD.facet AND j.node_hash=OLD.node_hash AND j.work_version=OLD.work_version AND j.completed_version=CASE OLD.complete WHEN 1 THEN OLD.work_version ELSE OLD.completed_version END AND j.last_turn=OLD.next_turn AND (j.cursor_destination,j.cursor_source,j.cursor_clock,j.cursor_set)=(OLD.next_destination,OLD.next_source,OLD.next_clock,OLD.next_set)) THEN RAISE(ABORT,'inventory matching coverage page progress incomplete') END;
 SELECT CASE WHEN OLD.set_count!=(SELECT count(*) FROM inventory_matching_coverage_page_dependents WHERE tenant=OLD.tenant AND page_id=OLD.page_id) OR OLD.row_count!=(SELECT count(*) FROM inventory_matching_coverage_page_candidates WHERE tenant=OLD.tenant AND page_id=OLD.page_id) OR EXISTS(SELECT 1 FROM inventory_matching_coverage_invalid_rows WHERE tenant=OLD.tenant AND page_id=OLD.page_id) THEN RAISE(ABORT,'inventory matching coverage page census changed') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM inventory_matching_coverage_invalid_configurations WHERE tenant=OLD.tenant AND page_id=OLD.page_id) THEN RAISE(ABORT,'inventory matching coverage configuration changed') END;
 SELECT CASE WHEN OLD.complete=1 AND EXISTS(SELECT 1 FROM inventory_matching_coverage_page_remaining WHERE tenant=OLD.tenant AND page_id=OLD.page_id) THEN RAISE(ABORT,'inventory matching coverage page range incomplete') END;
 SELECT CASE WHEN (SELECT count(*) FROM inventory_matching_coverage_rows q CROSS JOIN matching_work w WHERE q.tenant=OLD.tenant AND q.page_id=OLD.page_id AND w.tenant=q.tenant AND w.generation_id=OLD.generation_id AND w.destination=q.destination AND w.source_scope=q.source_scope AND w.record_key=q.record_key AND w.work_version=q.expected_work_version+1 AND w.completed_version=q.expected_completed_version AND w.source_config_version=q.source_config_version AND w.destination_config_version=q.destination_config_version AND w.due_at=0 AND w.hold_reason IS NULL)!=OLD.row_count THEN RAISE(ABORT,'inventory matching coverage work publication incomplete') END;
END;
CREATE TRIGGER inventory_matching_coverage_page_identity BEFORE UPDATE ON inventory_matching_coverage_pages WHEN (NEW.tenant,NEW.page_id,NEW.generation_id,NEW.scope_id,NEW.facet,NEW.node_hash,NEW.config_version,NEW.domain_version,NEW.source_set_version,NEW.signal_clock,NEW.work_version,NEW.completed_version,NEW.previous_turn,NEW.next_turn,NEW.previous_destination,NEW.previous_source,NEW.previous_clock,NEW.previous_set,NEW.next_destination,NEW.next_source,NEW.next_clock,NEW.next_set,NEW.limit_count,NEW.set_count,NEW.row_count,NEW.complete,NEW.lease_token,NEW.lease_fence,NEW.input_digest,NEW.prepared_at) IS NOT (OLD.tenant,OLD.page_id,OLD.generation_id,OLD.scope_id,OLD.facet,OLD.node_hash,OLD.config_version,OLD.domain_version,OLD.source_set_version,OLD.signal_clock,OLD.work_version,OLD.completed_version,OLD.previous_turn,OLD.next_turn,OLD.previous_destination,OLD.previous_source,OLD.previous_clock,OLD.previous_set,OLD.next_destination,OLD.next_source,OLD.next_clock,OLD.next_set,OLD.limit_count,OLD.set_count,OLD.row_count,OLD.complete,OLD.lease_token,OLD.lease_fence,OLD.input_digest,OLD.prepared_at) BEGIN SELECT RAISE(ABORT,'immutable inventory matching coverage page'); END;
CREATE TRIGGER inventory_matching_coverage_row_insert BEFORE INSERT ON inventory_matching_coverage_rows WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_coverage_pages h WHERE h.tenant=NEW.tenant AND h.page_id=NEW.page_id AND h.state='prepared' AND NOT EXISTS(SELECT 1 FROM inventory_matching_coverage_guards g WHERE g.tenant=h.tenant AND g.page_id=h.page_id)) BEGIN SELECT RAISE(ABORT,'inventory matching coverage rows closed'); END;
CREATE TRIGGER inventory_matching_coverage_row_update BEFORE UPDATE ON inventory_matching_coverage_rows BEGIN SELECT RAISE(ABORT,'immutable inventory matching coverage row'); END;
CREATE TRIGGER inventory_matching_coverage_page_delete BEFORE DELETE ON inventory_matching_coverage_pages WHEN OLD.state!='committed' OR OLD.prepared_at>unixepoch('subsec')*1000-604800000 BEGIN SELECT RAISE(ABORT,'retained inventory matching coverage page'); END;
CREATE TRIGGER inventory_matching_coverage_row_delete BEFORE DELETE ON inventory_matching_coverage_rows WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_coverage_pages h WHERE h.tenant=OLD.tenant AND h.page_id=OLD.page_id AND h.state='committed' AND h.prepared_at<unixepoch('subsec')*1000-604800000) BEGIN SELECT RAISE(ABORT,'retained inventory matching coverage row'); END;
CREATE TRIGGER inventory_matching_coverage_guard_update BEFORE UPDATE ON inventory_matching_coverage_guards BEGIN SELECT RAISE(ABORT,'immutable inventory matching coverage guard'); END;
CREATE TRIGGER inventory_matching_coverage_guard_delete BEFORE DELETE ON inventory_matching_coverage_guards WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_coverage_pages h WHERE h.tenant=OLD.tenant AND h.page_id=OLD.page_id AND h.state='committed' AND h.prepared_at<unixepoch('subsec')*1000-604800000) BEGIN SELECT RAISE(ABORT,'retained inventory matching coverage guard'); END;
